<?php
require_once __DIR__.'/includes/online_quiz.php';require_login();$user=current_user();
try{$monitor=oq_monitor((int)($_GET['id']??0),$user);$quiz=$monitor['quiz'];$review=null;$timeline=[];
    if(!empty($_GET['attempt'])){$aid=(int)$_GET['attempt'];$a=oq_attempt($aid,$user,false,true);if((int)$a['quiz_id']!==(int)$quiz['id'])throw new RuntimeException('Unavailable');$review=oq_result($aid,$user,true);$timeline=oq_timeline($aid,$user);}
}catch(Throwable $e){http_response_code(404);exit('Quiz not available.');}
require_once __DIR__.'/partials/online_quiz_shell.php';header('Cache-Control: no-store');
?>
