<?php if($review): ?><section class="oq-card" id="oq-attempt-review"><h2>Attempt <?php echo (int)$review['attempt_id']; ?> · <?php echo h($review['status']); ?></h2><?php if($review['flagged']): ?><p class="oq-error">Flagged for review — make a human academic decision using the timeline and student context.</p><?php endif; ?>
<form id="oq-review-form"><?php foreach($review['questions'] as $q): ?><div class="oq-review-row"><h3>Q<?php echo (int)$q['position']+1; ?> · <?php echo h($q['text']); ?></h3><p class="oq-prose">Student answer: <?php $answer=$q['answer'];foreach($q['options'] as $o)if($o['id']===$answer)$answer=$o['text'];echo h($answer?:'Unanswered'); ?></p><p>Accepted key: <?php echo h(implode('; ',array_map(function($k)use($q){foreach($q['options'] as $o)if($o['id']===$k)return $o['text'];return $k;},$q['key']??[]))?:'Manual review'); ?></p><div class="oq-form-grid"><label>Score / <?php echo h($q['marks']); ?><input type="number" min="0" max="<?php echo h($q['marks']); ?>" step="0.01" data-review-score="<?php echo (int)$q['id']; ?>" value="<?php echo h((string)$q['awarded_marks']); ?>"></label><label>Feedback<textarea data-review-feedback="<?php echo (int)$q['id']; ?>" rows="2"><?php echo h($q['feedback']??''); ?></textarea></label></div></div><?php endforeach; ?>
<?php if($review['status']!=='writing'): ?><label>Private integrity-review note<textarea id="oq-review-note" rows="3"><?php echo h($a['review_note']??''); ?></textarea></label><button class="btn primary" type="submit">Save marking &amp; review</button><?php endif; ?></form>
<h3>Integrity timeline</h3><div class="oq-table-wrap"><table class="oq-table"><thead><tr><th>Server time (WAT)</th><th>Event</th><th>Classification</th></tr></thead><tbody><?php foreach($timeline as $event): ?><tr><td><?php echo h($event['server_at']); ?></td><td><?php echo h($event['event_type']); ?></td><td><?php echo $event['is_violation']?'Violation '.(int)$event['warning_number']:'Neutral / observation'; ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?>
